+  assert.equal(isPlausibleScore(2147483647), true);
+  assert.equal(isPlausibleScore(-1), false);
+  assert.equal(isPlausibleScore(10.5), false);
+  assert.equal(isPlausibleScore(Number.POSITIVE_INFINITY), false);
+});
